-- ============================================================================
-- A11 - COMPLETE LOAD
-- MES (Work Centers + Shifts + Operation Confirmations per Production Order)
-- ============================================================================

-- FASE 1: DROP (cascade) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.OPERATION_CONFIRMATION CASCADE;
DROP TABLE INDUSTRIAL_DATA.WORK_CENTER CASCADE;
DROP TABLE INDUSTRIAL_DATA.SHIFT CASCADE;

-- FASE 2: CREATE CONFIG TABLES
CREATE TABLE INDUSTRIAL_DATA.SHIFT (SHIFT_CODE NVARCHAR(2) NOT NULL PRIMARY KEY, SHIFT_TEXT NVARCHAR(60) NOT NULL);
CREATE TABLE INDUSTRIAL_DATA.WORK_CENTER (WORK_CENTER_ID NVARCHAR(6) NOT NULL PRIMARY KEY, WORK_CENTER_TEXT NVARCHAR(60) NOT NULL, WERKS NVARCHAR(4) NOT NULL, FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS));

-- FASE 3: LOAD CONFIG DATA


-- FASE 4: CREATE OPERATION CONFIRMATION
CREATE TABLE INDUSTRIAL_DATA.OPERATION_CONFIRMATION (
  CONFIRMATION_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  AUFNR NVARCHAR(10) NOT NULL,
  OPERATION_NO INT NOT NULL,
  OPERATION_TEXT NVARCHAR(60) NOT NULL,
  WORK_CENTER_ID NVARCHAR(6) NOT NULL,
  SHIFT_CODE NVARCHAR(2) NOT NULL,
  QUANTITY_GOOD DECIMAL(15, 2) NOT NULL,
  QUANTITY_SCRAP DECIMAL(15, 2) NOT NULL,
  SETUP_TIME_MIN INT NOT NULL,
  RUN_TIME_MIN INT NOT NULL,
  CONFIRMATION_DATE DATE NOT NULL,
  FOREIGN KEY (AUFNR) REFERENCES INDUSTRIAL_DATA.PRODUCTION_ORDER(AUFNR),
  FOREIGN KEY (WORK_CENTER_ID) REFERENCES INDUSTRIAL_DATA.WORK_CENTER(WORK_CENTER_ID),
  FOREIGN KEY (SHIFT_CODE) REFERENCES INDUSTRIAL_DATA.SHIFT(SHIFT_CODE),
  CHECK (QUANTITY_GOOD >= 0),
  CHECK (QUANTITY_SCRAP >= 0)
);

-- FASE 5: LOAD OPERATION CONFIRMATIONS (94 apontamentos, variando por status da ordem)

-- FASE 6: VALIDACAO FINAL
SELECT 'A11 LOADED SUCCESSFULLY' FROM DUMMY;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.SHIFT;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.WORK_CENTER;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.OPERATION_CONFIRMATION;
SELECT AUFNR, COUNT(*) FROM INDUSTRIAL_DATA.OPERATION_CONFIRMATION GROUP BY AUFNR ORDER BY AUFNR;
SELECT TOP 5 AUFNR, OPERATION_NO, OPERATION_TEXT, WORK_CENTER_ID, QUANTITY_GOOD, QUANTITY_SCRAP FROM INDUSTRIAL_DATA.OPERATION_CONFIRMATION ORDER BY AUFNR, OPERATION_NO;
